SELECT s.nome, s.telefone, s.endereco, s.obs
FROM stg s
WHERE NOT EXISTS (
  SELECT 1 FROM cliente c
  WHERE c.deleted_at IS NULL
    AND LENGTH(COALESCE(s.tel_norm, '')) >= 8
    AND regexp_replace(COALESCE(c.telefone, ''), '\D', '', 'g') = s.tel_norm
);

